class UserDataModel {    UserDataModel({        required this.id,        required this.name,        required this.email,        required this.emailVerifiedAt,        required this.phone,        required this.photo,        required this.role,        required this.status,        required this.createdAt,        required this.updatedAt,    });    final int id;    final String name;    final String email;    final String emailVerifiedAt;    final String phone;    final String photo;    final String role;    final String status;    final DateTime? createdAt;    final DateTime? updatedAt;    factory UserDataModel.fromJson(Map<String, dynamic> json){        return UserDataModel(            id: json["id"] ?? 0,            name: json["name"] ?? "Name",            email: json["email"] ?? "zan_user@com.com",            emailVerifiedAt: json["email_verified_at"] ?? "false",            phone: json["phone"] ?? "",            photo: json["photo"] ?? "",            role: json["role"] ?? "",            status: json["status"] ?? "",            createdAt: DateTime.tryParse(json["created_at"] ?? ""),            updatedAt: DateTime.tryParse(json["updated_at"] ?? ""),        );    }    Map<String, dynamic> toJson() => {        "id": id,        "name": name,        "email": email,        "email_verified_at": emailVerifiedAt,        "phone": phone,        "photo": photo,        "role": role,        "status": status,        "created_at": createdAt?.toIso8601String(),        "updated_at": updatedAt?.toIso8601String(),    };}